algorithms.pseudocode:
function ENCODE(a0, a, rflR, p):
    require p : a0 = a            # p exists iff a == a0 on discrete types
    return transport(p, rflR)     # p ▸ rflR; along rfl this is rflR

function FIBREWISE_EQUIV(enc_S, dec_S, enc_T, dec_T):
    to_fun  := r -> enc_T(dec_S(r))    # R(a) -> (a0=a) -> R'(a)
    inv_fun := s -> enc_S(dec_T(s))    # R'(a) -> (a0=a) -> R(a)
    return (to_fun, inv_fun)
